-- September 2026 generated transaction history. Select the target database before importing.
-- Generated records for analytics testing; not evidence of actual business transactions.
-- 268 records across 18 randomly selected non-Sunday dates; other dates remain empty.
-- No records on Sundays: September 6, 13, 20, or 27.
-- Historical dates are generated independently of the currently configured weekly schedule.
-- Account names and service IDs are resolved from the existing database.
-- Teller IDs match the application's rules: Payment 5/8; Billing 10/11.
-- Positive ticket IDs 2026090101..2026093099 reserve a separate range for this file.
-- Existing records are not changed or removed. Reimporting skips matching transactions.
-- This is a separate additional dataset; it does not replace the earlier seed file's rows.
-- Populated dates:
-- 2026-09-01: 23 tickets
-- 2026-09-02: 14 tickets
-- 2026-09-03: 9 tickets
-- 2026-09-04: 23 tickets
-- 2026-09-05: 16 tickets
-- 2026-09-07: 9 tickets
-- 2026-09-08: 23 tickets
-- 2026-09-09: 10 tickets
-- 2026-09-12: 14 tickets
-- 2026-09-14: 9 tickets
-- 2026-09-16: 9 tickets
-- 2026-09-18: 24 tickets
-- 2026-09-19: 10 tickets
-- 2026-09-22: 10 tickets
-- 2026-09-24: 16 tickets
-- 2026-09-25: 14 tickets
-- 2026-09-26: 23 tickets
-- 2026-09-28: 12 tickets

SET @history_admin = (SELECT u.user_id FROM users u JOIN roles r ON r.role_id=u.role_id WHERE r.role_name='Admin' AND u.is_active=1 ORDER BY u.user_id LIMIT 1);
SET @history_customer = (SELECT u.user_id FROM users u JOIN roles r ON r.role_id=u.role_id WHERE r.role_name='Customer' AND u.is_active=1 ORDER BY u.user_id LIMIT 1);
SET @history_customer_name = (SELECT COALESCE(NULLIF(TRIM(CONCAT_WS(' ', first_name, last_name)), ''), username) FROM users WHERE user_id=@history_customer);
SET @history_payment_service = (SELECT service_id FROM services WHERE service_name='Payment' AND is_active=1 ORDER BY service_id LIMIT 1);
SET @history_billing_service = (SELECT service_id FROM services WHERE service_name IN ('Notice of Billing','Billing') AND is_active=1 ORDER BY service_id LIMIT 1);

DROP TEMPORARY TABLE IF EXISTS september_2026_history_rows;
CREATE TEMPORARY TABLE september_2026_history_rows LIKE queue_ticket_history;

START TRANSACTION;

SELECT incoming.ticket_id, incoming.ticket_number, incoming.service_id, incoming.customer_id, incoming.customer_name, incoming.status, incoming.priority, incoming.created_at, incoming.called_at, incoming.completed_at, incoming.assigned_user_id, incoming.archived_at, incoming.archived_by
FROM september_2026_history_rows incoming
WHERE DAYOFWEEK(incoming.created_at) <> 1
  AND NOT EXISTS (
    SELECT 1 FROM queue_ticket_history existing
    WHERE existing.ticket_id = incoming.ticket_id
      AND existing.ticket_number = incoming.ticket_number
      AND existing.created_at = incoming.created_at
  );
COMMIT;
DROP TEMPORARY TABLE september_2026_history_rows;

-- Check only the records generated by this file.
SELECT DATE(created_at) AS transaction_date, DAYNAME(created_at) AS weekday,
       COUNT(*) AS tickets, SUM(status='completed') AS served,
       SUM(status='skipped') AS skipped, SUM(status='cancelled') AS cancelled
FROM queue_ticket_history
WHERE ticket_id BETWEEN 2026090101 AND 2026093099
  AND created_at >= '2026-09-01' AND created_at < '2026-10-01'
GROUP BY DATE(created_at), DAYNAME(created_at)
ORDER BY transaction_date;
